const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Enable gift wrap on cart item CI-0011
db.prepare('UPDATE cart_items SET gift_wrap = 1 WHERE cart_item_id = ?').run('CI-0011');

// Update the cart's gift_wrap_fee and total
const cartId = 'CART-user_fbab7801';
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get(cartId);

// Calculate total gift wrap fee for all items in this cart
const items = db.prepare('SELECT ci.*, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id = ?').all('user_fbab7801');
let giftWrapFee = 0;
for (const item of items) {
  if (item.gift_wrap) {
    giftWrapFee += 5 * item.quantity;
  }
}

// Update cart totals
const newTotal = cart.subtotal - cart.discount_amount + giftWrapFee - cart.loyalty_discount + cart.shipping_cost;
db.prepare('UPDATE carts SET gift_wrap_fee = ?, total = ? WHERE cart_id = ?').run(giftWrapFee, newTotal, cartId);

